// Node.js built-ins that CF Workers DOES provide via nodejs_compat flag.
// Mark these as external so esbuild leaves the imports as-is; the CF runtime resolves them.
const NODE_BUILTINS_AVAILABLE_IN_CF = [
  "node:assert", "node:async_hooks", "node:buffer", "node:crypto",
  "node:diagnostics_channel", "node:events", "node:module",
  "node:path", "node:perf_hooks", "node:process", "node:querystring",
  "node:stream", "node:stream/consumers", "node:stream/promises",
  "node:stream/web", "node:string_decoder", "node:timers",
  "node:timers/promises", "node:url", "node:util", "node:util/types",
  "node:worker_threads", "node:zlib",
  // Without "node:" prefix (legacy imports)
  "assert", "async_hooks", "buffer", "crypto", "diagnostics_channel",
  "events", "module", "path", "perf_hooks", "process", "querystring",
  "stream", "string_decoder", "timers", "url", "util", "zlib",
  // Node 22.5+ built-in pulled in by undici@7 — not available in Workers but
  // will only be referenced inside try/catch or lazy code; mark external so esbuild
  // leaves the import as-is and the CF runtime handles it gracefully.
  "node:sqlite",
];

// Node.js APIs NOT available in CF Workers even with nodejs_compat.
// These must be STUBBED (not external) — if left external the CF runtime
// would try to resolve them and fail at startup.
const SHIMS_DIR = path.join(__dirname, "src/shims");
